select * from ( select 'Opening' AS DocumentType, @FromDate AS CreateDate, TABopening.CustomerID, TABopening.Name, -1 AS SourceID, SUM(TABopening.Amount) as Amount, '' AS InstrumentNo, '' Comments, '' AS InvoiceNumbers, '' AS InvoiceDocumentNo, '' AS DocumentNo, @FromDate AS DocumentDate, 0 AS FreightAmount, 0 AS ForAlhajAmount , TABopening.StatusCode, '' AS FAX, '' AS SheetNo from ( SELECT FINTAB.DocumentType, Fintab.CreateDate, FINTAB.CustomerID, FINTAB.Name, FinTab.SourceID, SUM(FINTAB.Amount) as Amount, FINTAB.InstrumentNo, FINTAB.Comments, FINTAB.InvoiceNumbers, FINTAB.InvoiceDocumentNo, FINTAB.DocumentNo, FINTAB.DocumentDate, FINTAB.FreightAmount, FINTAB.ForAlhajAmount , FINTAB.StatusCode FROM ( Select 'Opening' as DocumentType, @FromDate AS CreateDate, openingTAB.CustomerID, openingTAB.Name, -1 AS SourceID, sum(openingTAB.Amount) as Amount, '' as InstrumentNo, '' as Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, '' as DocumentNo, @FromDate as DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount , openingTAB.StatusCode From ( ---------- OPENING BALANCE VENDOR INVOICE ---------- SELECT 0 as Amount, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS Name, AR_ReceiptCustomerDetail.ReceiptCustomerID as SourceID ,AR_ReceiptTransactionHeader.StatusCode FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.Status = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID
INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptAccountsDetail.Status = 1 {7} WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND convert(date,AR_ReceiptTransactionHeader.DocumentDate) < @FromDate And SET_DocumentType.status = 1 {4} GROUP BY AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.ReceiptCustomerID,AR_ReceiptTransactionHeader.StatusCode ) OpeningTAB GROUP BY OpeningTAB.CustomerID ,OpeningTAB.Name,OpeningTAB.StatusCode
UNION ALL
select distinct TABInvoice.DocumentType, TABInvoice.CreateDate, TABInvoice.CustomerID, TABInvoice.BusinessPartnerName, TABInvoice.SourceID, TABInvoice.Amount, TABInvoice.InstrumentNo, TABInvoice.Comments, TABInvoice.InvoiceNumbers, TABInvoice.InvoiceDocumentNo, TABInvoice.DocumentNo, TABInvoice.DocumentDate, TABInvoice.FreightAmount, TABInvoice.ForAlhajAmount ,TABInvoice.StatusCode from (
SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID and AR_InvoiceSupplierDetail.BusinessPartnerTypeID = CUS.TypeCode And AR_InvoiceSupplierDetail.Status = 1
) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status = 1 And CUS.Status= 1 ) else ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID And AR_InvoiceHeader.Status= 1 And CUS.Status= 1 ) end as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) else ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID And AR_InvoiceHeader.Status= 1 And CUS.Status= 1 ) end as BusinessPartnerName, AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid else (AR_InvoiceHeader.AmountPaid+AR_InvoiceHeader.FreightAmount - isnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end ) end as Amount, '0' AS InstrumentNo, AR_InvoiceHeader.Description AS Comments, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_InvoiceHeader.StatusCode FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 --AND AR_InvoiceHeader.StatusCode = 1 LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.Status = 1 LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.Status = 1 LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID
LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode {7} WHERE AR_InvoiceHeader.CompanyID = @companyId AND AR_InvoiceHeader.PeriodID = @PeriodId AND convert(date,AR_InvoiceHeader.InvoiceDate) < @FromDate And SET_DocumentType.Status = 1 {5} --and SET_DocumentType.documenttype not like '%Opening%' ) TABInvoice where TABInvoice.companyID = @companyId {8} {9}
---------------------Vendor INvoice Supplier Detail
union ALL
select distinct TABInvoice.DocumentType, TABInvoice.CreateDate, TABInvoice.CustomerID, TABInvoice.BusinessPartnerName, TABInvoice.SourceID, TABInvoice.Amount, TABInvoice.InstrumentNo, TABInvoice.Comments, TABInvoice.InvoiceNumbers, TABInvoice.InvoiceDocumentNo, TABInvoice.DocumentNo, TABInvoice.DocumentDate, TABInvoice.FreightAmount, TABInvoice.ForAlhajAmount ,TABInvoice.StatusCode from ( ---------- Vendor Invoice ---------- SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID and AR_InvoiceSupplierDetail.BusinessPartnerTypeID = CUS.TypeCode And AR_InvoiceSupplierDetail.Status = 1
) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) BusinessPartnerName, AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end as Amount, '0' AS InstrumentNo, AR_InvoiceSupplierDetail.Narration AS Comments, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_InvoiceHeader.StatusCode FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 --AND AR_InvoiceHeader.StatusCode = 1 Inner JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.Status = 1 Inner JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.Status = 1 Inner JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 inner JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceSupplierDetail.SupplierID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceSupplierDetail.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceSupplierDetail.PeriodID
inner JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_InvoiceSupplierDetail.BusinessPartnerTypeID {7} WHERE AR_InvoiceHeader.CompanyID = @companyId AND AR_InvoiceHeader.PeriodID = @PeriodId AND convert(date,AR_InvoiceHeader.InvoiceDate) < @FromDate And SET_DocumentType.Status = 1 {5} --and SET_DocumentType.documenttype not like '%Opening%' ) TABInvoice where TABInvoice.companyID = @companyId {8} {9}
---------------------------------------------------
UNION ALL ---------- Payment ---------- SELECT SET_DocumentType.DocumentType, AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PaymentHeader.PaymentID as SourceID, (Case AP_PaymentSupplierDetail.TransactionType when 'Debit' then AP_PaymentSupplierDetail.Amount else AP_PaymentSupplierDetail.Amount * -1 end) as Amount, AP_PaymentHeader.PaymentServerOrderNo AS InstrumentNo, IsNull(AP_PaymentHeader.Comments, '') + (Case When AP_PaymentHeader.ReversalComments IS NULL Then '' Else ' ' + AP_PaymentHeader.ReversalComments End) AS Comments, case when AP_PaymentHeader.POHeaderID is null then (ISNULL( ( SELECT STUFF( ( SELECT AR_InvoiceHeader.InvoiceNumber FROM AP_PaymentHeader childPayment LEFT JOIN AP_PaymentInvoicesDetail ON AP_PaymentInvoicesDetail.PaymentHeaderID = childPayment.PaymentID AND AP_PaymentInvoicesDetail.CompanyID = childPayment.CompanyID AND AP_PaymentInvoicesDetail.PeriodID = childPayment.PeriodID AND AP_PaymentInvoicesDetail.Status = 1 LEFT JOIN AR_InvoiceHeader ON AR_InvoiceHeader.InvoiceID = AP_PaymentInvoicesDetail.InvoiceHeaderID AND AR_InvoiceHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID AND AR_InvoiceHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID AND AR_InvoiceHeader.Status = 1 LEFT JOIN AR_InvoiceDetail ON AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID AND AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status = 1 where childPayment.PaymentID = payment.PaymentID and childPayment.CompanyID = payment.CompanyID and childPayment.PeriodID = payment.PeriodID And childPayment.Status = 1 ORDER BY AR_InvoiceHeader.InvoiceNumber FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceNumbers FROM AP_PaymentHeader payment where payment.PaymentID = AP_PaymentHeader.PaymentID and payment.CompanyID = AP_PaymentHeader.CompanyID and payment.PeriodID = AP_PaymentHeader.PeriodID And Payment.Status = 1 ), '')) else (Select DocumentNumber from AP_PurchaseOrderHeader where AP_PurchaseOrderHeader.POHeaderID = AP_PaymentHeader.POHeaderID and AP_PurchaseOrderHeader.CompanyID = AP_PaymentHeader.CompanyID and AP_PurchaseOrderHeader.PeriodID = AP_PaymentHeader.PeriodID ) end as InvoiceNumbers, ISNULL( ( SELECT STUFF( ( SELECT ', ' + AP_PaymentDetail.InvoiceDocumentNo FROM AP_PaymentDetail WHERE payment1.PaymentID = AP_PaymentDetail.PaymentHeaderID And AP_PaymentDetail.Status = 1 ORDER BY AP_PaymentDetail.InvoiceDocumentNo FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceDocumentNo FROM AP_PaymentHeader payment1 where payment1.PaymentID = AP_PaymentHeader.PaymentID and payment1.CompanyID = AP_PaymentHeader.CompanyID and payment1.PeriodID = AP_PaymentHeader.PeriodID ), '') as InvoiceDocumentNo, ISNULL(AP_PaymentHeader.DocumentNo, 0) AS DocumentNo, AP_PaymentHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount , IsNull(AP_Payment_AccountsDetail.Amount, 0) * -1 As ForAlhajAmount ,AP_PaymentHeader.StatusCode FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 --AND AP_PaymentHeader.StatusCode = 1 INNER Join AP_PaymentSupplierDetail on AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID and AP_PaymentSupplierDetail.Status = 1 INNER JOIN AR_SET_Customer ON AP_PaymentSupplierDetail.SupplierID = AR_SET_Customer.CustomerID --AND AP_PaymentSupplierDetail.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentSupplierDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 -- AND AR_SET_Customer.IsActive = 1 left join AP_Payment_AccountsDetail on AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_Payment_AccountsDetail.IsBP <> 0 and AP_Payment_AccountsDetail.TransactionType = 'Credit' and AP_Payment_AccountsDetail.Status = 1 INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID and AR_SET_BusinessPartnerTypes.TypeCode = AP_PaymentSupplierDetail.BusinessPartnerTypeID --------------------------------------------------------------------------------------------------- WHERE AP_PaymentHeader.CompanyID = @CompanyId AND AP_PaymentHeader.PeriodID = @PeriodId AND convert(date,AP_PaymentHeader.DocumentDate) < @FromDate {0} {1} {6} GROUP BY AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AP_PaymentSupplierDetail.PaymentSupplierID, AP_PaymentSupplierDetail.TransactionType, AP_PaymentSupplierDetail.Amount, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.DocumentDate, SET_DocumentType.DocumentType, AP_PaymentHeader.PaymentID, AP_PaymentHeader.CompanyID, AP_PaymentHeader.PeriodID, AP_PaymentHeader.Comments, AP_PaymentHeader.POHeaderID, AP_PaymentHeader.PaymentServerOrderNo, AP_Payment_AccountsDetail.Amount, AP_PaymentHeader.ReversalComments ,AP_PaymentHeader.StatusCode UNION ALL
-- PAYMENT -- SINGLE BUSINESS PARTNER CASE SELECT SET_DocumentType.DocumentType, AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PaymentHeader.PaymentID as SourceID, (Case when AP_PaymentHeader.CustomerTransactionType is not null then AP_PaymentHeader.Amount * -1 else AP_PaymentHeader.Amount end) as Amount, AP_PaymentHeader.PaymentServerOrderNo AS InstrumentNo, AP_PaymentHeader.Comments + (Case When AP_PaymentHeader.ReversalComments IS NULL Then '' Else ' ' + AP_PaymentHeader.ReversalComments End) AS Comments, case when AP_PaymentHeader.POHeaderID is null then (ISNULL( ( SELECT STUFF( ( SELECT distinct AR_InvoiceHeader.InvoiceNumber FROM AP_PaymentHeader childPayment LEFT JOIN AP_PaymentInvoicesDetail ON AP_PaymentInvoicesDetail.PaymentHeaderID = childPayment.PaymentID AND AP_PaymentInvoicesDetail.CompanyID = childPayment.CompanyID AND AP_PaymentInvoicesDetail.PeriodID = childPayment.PeriodID AND AP_PaymentInvoicesDetail.Status = 1 LEFT JOIN AR_InvoiceHeader ON AR_InvoiceHeader.InvoiceID = AP_PaymentInvoicesDetail.InvoiceHeaderID AND AR_InvoiceHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID AND AR_InvoiceHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID AND AR_InvoiceHeader.Status = 1 LEFT JOIN AR_InvoiceDetail ON AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID AND AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status = 1 where childPayment.PaymentID = payment.PaymentID and childPayment.CompanyID = payment.CompanyID and childPayment.PeriodID = payment.PeriodID And childPayment.Status = 1 ORDER BY AR_InvoiceHeader.InvoiceNumber FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 0, '') AS InvoiceNumbers FROM AP_PaymentHeader payment where payment.PaymentID = AP_PaymentHeader.PaymentID and payment.CompanyID = AP_PaymentHeader.CompanyID and payment.PeriodID = AP_PaymentHeader.PeriodID and payment.status = 1
), '')) else (Select DocumentNumber from AP_PurchaseOrderHeader where AP_PurchaseOrderHeader.POHeaderID = AP_PaymentHeader.POHeaderID and AP_PurchaseOrderHeader.CompanyID = AP_PaymentHeader.CompanyID and AP_PurchaseOrderHeader.PeriodID = AP_PaymentHeader.PeriodID ) end as InvoiceNumbers, ISNULL( ( SELECT STUFF( ( SELECT ', ' + AP_PaymentDetail.InvoiceDocumentNo FROM AP_PaymentDetail WHERE payment1.PaymentID = AP_PaymentDetail.PaymentHeaderID And AP_PaymentDetail.status = 1 ORDER BY AP_PaymentDetail.InvoiceDocumentNo FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceDocumentNo FROM AP_PaymentHeader payment1 where payment1.PaymentID = AP_PaymentHeader.PaymentID and payment1.CompanyID = AP_PaymentHeader.CompanyID and payment1.PeriodID = AP_PaymentHeader.PeriodID And payment1.Status = 1 ), '') as InvoiceDocumentNo, ISNULL(AP_PaymentHeader.DocumentNo, 0) AS DocumentNo, AP_PaymentHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount , IsNull(AP_Payment_AccountsDetail.Amount, 0) * -1 As ForAlhajAmount ,AP_PaymentHeader.StatusCode FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 --AND AP_PaymentHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 -- AND AR_SET_Customer.IsActive = 1 INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
left join AP_Payment_AccountsDetail on AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_Payment_AccountsDetail.IsBP <> 0 and AP_Payment_AccountsDetail.TransactionType = 'Credit' and AP_Payment_AccountsDetail.Status = 1 {7} WHERE AP_PaymentHeader.CompanyID = @CompanyId AND AP_PaymentHeader.PeriodID = @PeriodId AND convert(date,AP_PaymentHeader.DocumentDate) < @FromDate And SET_DocumentType.Status = 1 {0} {1} {6} GROUP BY AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AP_PaymentHeader.CustomerTransactionType, AP_PaymentHeader.Amount, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.DocumentDate, SET_DocumentType.DocumentType, AP_PaymentHeader.PaymentID, AP_PaymentHeader.CompanyID, AP_PaymentHeader.PeriodID,AP_PaymentHeader.Comments, AP_PaymentHeader.POHeaderID,AP_PaymentHeader.PaymentServerOrderNo ,AP_Payment_AccountsDetail.Amount, AP_PaymentHeader.ReversalComments ,AP_PaymentHeader.StatusCode UNION ALL -----------Sale Invoice Header----------- select TAB.DocumentType,TAB.CreateDate,CustomerID,BusinessPartnerName,SourceID,round(sum(Amount),2) as Amount,InstrumentNo,Comments,InvoiceNumbers,InvoiceDocumentNo,DocumentNo,DocumentDate,FreightAmount,ForAlhajAmount,StatusCode from ( SELECT SET_DocumentType.DocumentType, SAL_InvoiceHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_InvoiceHeader.InvoiceID as SourceID, case when SET_DocumentType.DocumentType = 'Credit Note' then SAL_InvoiceHeader.AmountPaid * -1 else
case when isnull((select FieldValue1 from Set_Parameter where FieldName = 'SROPercent'),0) != 0 then ( case isnull(AR_SET_BusinessPartner.BusinessPartnerName,'') when 'S.R.O' then (case isnull(Fabrics_SAL_InvoiceDetail.FurtherTax,0) when 0 then ((Fabrics_SAL_InvoiceDetail.Amount * (Fabrics_SAL_InvoiceDetail.GST + Fabrics_SAL_InvoiceDetail.FurtherTax)/100 )* isnull((select FieldValue1 from Set_Parameter where FieldName = 'SROPercent'),0) / 100) else 0 end) when 'Customer' then ( case isnull(FurtherTax,0) when 0 then SAL_InvoiceHeader.AmountPaid - ((Fabrics_SAL_InvoiceDetail.Amount * (GST + FurtherTax)/100 ) * isnull((select FieldValue1 from Set_Parameter where FieldName = 'SROPercent'),0) / 100) else SAL_InvoiceHeader.AmountPaid + (SAL_InvoiceHeader.AmountPaid * FurtherTax / 100) end ) else 0 end ) else SAL_InvoiceHeader.AmountPaid end end as Amount, '0' AS InstrumentNo, SAL_InvoiceHeader.description AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, SAL_InvoiceHeader.InvoiceDate AS DocumentDate, CASE WHEN GL_TransactionDetail.TransactionType = 'Debit' THEN ISNULL(SAL_InvoiceHeader.FreightAmount * -1, 0) else ISNULL(SAL_InvoiceHeader.FreightAmount, 0) end as FreightAmount , 0 As ForAlhajAmount,SAL_InvoiceHeader.StatusCode FROM SET_DocumentType INNER JOIN SAL_InvoiceHeader ON SET_DocumentType.CompanyID = SAL_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_InvoiceHeader.InvoiceType AND SAL_InvoiceHeader.Status = 1 left join Fabrics_SAL_InvoiceDetail on Fabrics_SAL_InvoiceDetail.InvoiceHeaderID = SAL_InvoiceHeader.InvoiceID and Fabrics_SAL_InvoiceDetail.status = 1 INNER JOIN AR_SET_Customer ON SAL_InvoiceHeader.CustomerID = AR_SET_Customer.CustomerID-- AND SAL_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 --AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode --AND AR_SET_BusinessPartner.BusinessPartnerName = 'Customer' LEFT JOIN GL_TransactionDetail ON GL_TransactionDetail.CodeCombinationID = SAL_InvoiceHeader.FreightCode AND GL_TransactionDetail.SourceHeaderID = SAL_InvoiceHeader.InvoiceID AND GL_TransactionDetail.CompanyID = SAL_InvoiceHeader.CompanyID AND GL_TransactionDetail.PeriodID = SAL_InvoiceHeader.PeriodID AND GL_TransactionDetail.Status = 1 {7} WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND convert(date,SAL_InvoiceHeader.InvoiceDate) < @FromDate AND SET_DocumentType.Status= 1 {3} GROUP BY SAL_InvoiceHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceID, SAL_InvoiceHeader.AmountPaid, SAL_InvoiceHeader.InvoiceNumber, SAL_InvoiceHeader.InvoiceDate, SET_DocumentType.DocumentType, GL_TransactionDetail.TransactionType, SAL_InvoiceHeader.FreightAmount,SAL_InvoiceHeader.StatusCode ,GL_TransactionDetail.Amount
,Fabrics_SAL_InvoiceDetail.Amount,Fabrics_SAL_InvoiceDetail.GST,Fabrics_SAL_InvoiceDetail.FurtherTax ,AR_SET_BusinessPartner.BusinessPartnerName,SAL_InvoiceHeader.description ) as TAB group by TAB.DocumentType,TAB.CreateDate,CustomerID,BusinessPartnerName,SourceID,InstrumentNo,Comments,InvoiceNumbers,InvoiceDocumentNo,DocumentNo,DocumentDate,FreightAmount,ForAlhajAmount,StatusCode
union all --RECEIPT TRANSACTION SELECT distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, case when (select DocumentType from Set_documentTYpe where Set_documentTYpe.status= 1 And Set_documentTYpe.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID) like 'Receipt Against Sale%' then (select sum(Amount) from AR_ReceiptInvoicesDetail where AR_ReceiptInvoicesDetail.status = 1 And ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID) *-1 else AR_ReceiptTransactionHeader.Amount * -1 end as Amount, max(AR_ReceiptBanksDetail.InstrumentNo) AS InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_ReceiptTransactionHeader.StatusCode FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 left join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.status=1 INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode and AR_ReceiptTransactionHeader.BusinessPartnerTypeID = AR_SET_BusinessPartner.BusinessPartnerID Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptAccountsDetail.Status = 1 {7} WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND convert(date,AR_ReceiptTransactionHeader.DocumentDate) < @FromDate And SET_DocumentType.Status = 1 and AR_ReceiptTransactionHeader.ReceiptTransactionID not in ( select ReceiptHeaderID from AR_ReceiptCustomerDetail inner join AR_ReceiptTransactionHeader RecHDR on RecHDR.ReceiptTransactionID = AR_ReceiptTransactionHeader.ReceiptTransactionID and RecHDR.CompanyID = AR_ReceiptTransactionHeader.CompanyID and RecHDR.PeriodID = AR_ReceiptTransactionHeader.PeriodID and RecHDR.Status = 1 inner join set_documentType on set_documentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID and set_documentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID and set_documentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID {7} where AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and set_documentType.documentType not like 'Carriage Contractor Adjustment' and set_documentType.documentType not like 'Receipt Against Sale Invoices' and AR_ReceiptCustomerDetail.Status = 1 ) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptTransactionHeader.ReceiptTransactionID, AR_ReceiptAccountsDetail.ReceiptHeaderID, AR_ReceiptAccountsDetail.ReceiptAccountID,AR_ReceiptAccountsDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, ReversalComments ,AR_ReceiptTransactionHeader.StatusCode,AR_ReceiptTransactionHeader.DocumentTypeID
UNION ALL -- Receipt Transaction Without Opening SELECT SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, Case when AR_ReceiptCustomerDetail.TransactionType = 'Debit' then AR_ReceiptCustomerDetail.Amount else AR_ReceiptCustomerDetail.Amount * -1 end as Amount, max(AR_ReceiptBanksDetail.InstrumentNo) AS InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_ReceiptTransactionHeader.StatusCode FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 left join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.status=1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.Status = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID and AR_ReceiptCustomerDetail.BusinessPartnerTypeID = AR_SET_BusinessPartnerTypes.TypeCode {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptAccountsDetail.Status = 1 {7} WHERE AR_SET_Customer.PeriodID = @PeriodID AND convert(date,AR_ReceiptTransactionHeader.DocumentDate) < @FromDate --AR_SET_Customer.CompanyID = @CompanyID AND and SET_DocumentType.DocumentType not like '%opening%' AND SET_DocumentType.Status = 1 {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.ReceiptCustomerID, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, AR_ReceiptTransactionHeader.ReversalComments,AR_ReceiptTransactionHeader.ReceiptTransactionID,AR_ReceiptTransactionHeader.StatusCode
UNION ALL -- Receipt Transaction [Only Opening]
SELECT SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptCustomerDetail.ReceiptCustomerID as SourceID, Case when AR_ReceiptCustomerDetail.TransactionType = 'Debit' then AR_ReceiptCustomerDetail.Amount else AR_ReceiptCustomerDetail.Amount * -1 end as Amount, '0' AS InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_ReceiptTransactionHeader.StatusCode FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.Status = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID and AR_ReceiptCustomerDetail.BusinessPartnerTypeID = AR_SET_BusinessPartnerTypes.TypeCode {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID And AR_ReceiptAccountsDetail.Status = 1 {7} WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND convert(date,AR_ReceiptTransactionHeader.DocumentDate) < @FromDate And SET_DocumentType.Status= 1 and SET_DocumentType.DocumentType like '%opening%' {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.ReceiptCustomerID, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, Comments, AR_ReceiptTransactionHeader.ReversalComments,AR_ReceiptTransactionHeader.StatusCode
UNION ALL -- Commission On Receipt SELECT SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, ((AR_ReceiptTransactionHeader.Amount * AR_ReceiptTransactionHeader.CommissionPercentage)/100) * -1 as Amount, '0' AS InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_ReceiptTransactionHeader.StatusCode FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.EmployeeID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 -- AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptAccountsDetail.Status = 1 {7} WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND convert(date,AR_ReceiptTransactionHeader.DocumentDate) < @FromDate And SET_DocumentType.Status= 1 {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptTransactionHeader.ReceiptTransactionID, AR_ReceiptTransactionHeader.CommissionPercentage, AR_ReceiptAccountsDetail.ReceiptHeaderID, AR_ReceiptAccountsDetail.ReceiptAccountID,AR_ReceiptAccountsDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, Comments, ReversalComments ,AR_ReceiptTransactionHeader.StatusCode
-------- SALE DISCOUNT -----------
union All SELECT distinct SET_DocumentType.DocumentType, SAL_DiscountTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_DiscountTransactionHeader.DiscountTransactionHeaderID as SourceID, (SAL_DiscountTransactionHeader.CalculatedAmount * -1) as Amount, '0' AS InstrumentNo, '' AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_DiscountTransactionHeader.DiscountTransactionHeaderID, 0) AS DocumentNo, SAL_DiscountTransactionHeader.RunDateTime AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount , 1 as StatusCode FROM SET_DocumentType INNER JOIN SAL_DiscountTransactionHeader ON SET_DocumentType.CompanyID = SAL_DiscountTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_DiscountTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_DiscountTransactionHeader.DocumentTypeID And SAL_DiscountTransactionHeader.Status= 1 INNER JOIN AR_SET_Customer ON SAL_DiscountTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_DiscountTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_DiscountTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 -- AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode {7} WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND convert(date,SAL_DiscountTransactionHeader.RunDateTime) < @FromDate And SET_DocumentType.status= 1 ) AS FINTAB GROUP BY DocumentType, CreateDate, CustomerID, NAME, SourceID, InstrumentNo, Comments, InvoiceNumbers, InvoiceDocumentNo, DocumentNo, DocumentDate, FreightAmount, ForAlhajAmount , StatusCode ) as TABopening -- For Transation type Filter {12} GROUP BY TABopening.CustomerID, TABopening.Name,TABopening.StatusCode
UNION ALL
select * from ( SELECT FINTAB.DocumentType, Fintab.CreateDate, FINTAB.CustomerID, FINTAB.Name, FinTab.SourceID, SUM(FINTAB.Amount) as Amount, FINTAB.InstrumentNo, FINTAB.Comments, FINTAB.InvoiceNumbers, FINTAB.InvoiceDocumentNo, FINTAB.DocumentNo, FINTAB.DocumentDate, FINTAB.FreightAmount, FINTAB.ForAlhajAmount ,FINTAB.StatusCode, FINTAB.FAX, FINTAB.SheetNo FROM ( Select 'Opening' as DocumentType, @FromDate AS CreateDate, OpeningTAB.CustomerID, openingTAB.Name, -1 AS SourceID, sum(openingTAB.Amount) as Amount, '' as InstrumentNo, '' as Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, '' as DocumentNo, @FromDate as DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount, 1 as StatusCode, '' AS FAX, '' AS SheetNo From ( SELECT 0 as Amount, 0 AS CustomerID, '' AS Name, 0 as SourceID FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.Status = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptAccountsDetail.Status = 1 {7} WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND convert(date,AR_ReceiptTransactionHeader.DocumentDate) < @FromDate And SET_DocumentType.Status= 1 {0} {1} {4} GROUP BY AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.ReceiptCustomerID ) OpeningTAB GROUP BY OpeningTAB.CustomerID, OpeningTAB.Name
UNION ALL
select distinct TABInvoice.DocumentType, TABInvoice.CreateDate, TABInvoice.CustomerID, TABInvoice.BusinessPartnerName, TABInvoice.SourceID, TABInvoice.Amount, TABInvoice.InstrumentNo, TABInvoice.Comments, TABInvoice.InvoiceNumbers, TABInvoice.InvoiceDocumentNo, TABInvoice.DocumentNo, TABInvoice.DocumentDate, TABInvoice.FreightAmount, TABInvoice.ForAlhajAmount , TABInvoice.StatusCode, '' AS FAX, '' AS SheetNo from ( ---------- Vendor Invoice ---------- SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID and AR_InvoiceSupplierDetail.BusinessPartnerTypeID = CUS.TypeCode And AR_InvoiceSupplierDetail.Status= 1
) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) else ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID And AR_InvoiceHeader.Status= 1 And CUS.Status= 1 ) end as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, case when AR_InvoiceHeader.vendorID is null then ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) else ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceHeader.vendorID = CUS.CustomerID --AND AR_InvoiceHeader.CompanyID = CUS.CompanyID AND AR_InvoiceHeader.PeriodID = CUS.PeriodID And AR_InvoiceHeader.Status= 1 And CUS.status= 1 ) end as BusinessPartnerName, AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, case when AR_InvoiceHeader.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid else (AR_InvoiceHeader.AmountPaid+AR_InvoiceHeader.FreightAmount - isnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end ) end as Amount, '0' AS InstrumentNo, AR_InvoiceHeader.Description AS Comments, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_InvoiceHeader.StatusCode FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 --AND AR_InvoiceHeader.StatusCode = 1 LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.Status = 1 LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.Status = 1 LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode {7} WHERE AR_InvoiceHeader.CompanyID = @companyId AND AR_InvoiceHeader.PeriodID = @PeriodId AND convert(date,AR_InvoiceHeader.InvoiceDate) BETWEEN @FromDate AND @ToDate And SET_DocumentType.status= 1 {5} ) TABInvoice where TABInvoice.companyID = @companyId {8} {9}
union All --------------Vendor Invoice Supplier select distinct TABInvoice.DocumentType, TABInvoice.CreateDate, TABInvoice.CustomerID, TABInvoice.BusinessPartnerName, TABInvoice.SourceID, TABInvoice.Amount, TABInvoice.InstrumentNo, TABInvoice.Comments, TABInvoice.InvoiceNumbers, TABInvoice.InvoiceDocumentNo, TABInvoice.DocumentNo, TABInvoice.DocumentDate, TABInvoice.FreightAmount, TABInvoice.ForAlhajAmount , TABInvoice.StatusCode, '' AS FAX, '' AS SheetNo from ( ---------- Vendor Invoice ---------- SELECT distinct AR_InvoiceHeader.companyID, Set_DocumentType.TransactionType, case when AR_SET_BusinessPartnerTypes.TypeCode is null then ( select top 1 CUS.TypeCode from AR_SET_BusinessPartnerTypes CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.BusinessPartnerID AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID and AR_InvoiceSupplierDetail.BusinessPartnerTypeID = CUS.TypeCode And AR_InvoiceSupplierDetail.Status= 1
) else AR_SET_BusinessPartnerTypes.TypeCode end as TypeCode, ( select CUS.CustomerID from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) as CustomerID, SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, ( select CUS.CustomerName from AR_SET_Customer CUS where AR_InvoiceSupplierDetail.SupplierID = CUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = CUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = CUS.PeriodID And AR_InvoiceSupplierDetail.Status= 1 And CUS.Status= 1 ) BusinessPartnerName, AR_InvoiceSupplierDetail.InvoiceSupplierID as SourceID, Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end as Amount, '0' AS InstrumentNo, AR_InvoiceSupplierDetail.Narration AS Comments, AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_InvoiceHeader.StatusCode FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 --AND AR_InvoiceHeader.StatusCode = 1 Inner JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.Status = 1 Inner JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.Status = 1 Inner JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 inner JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceSupplierDetail.SupplierID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceSupplierDetail.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceSupplierDetail.PeriodID inner JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_InvoiceSupplierDetail.BusinessPartnerTypeID {7} WHERE AR_InvoiceHeader.CompanyID = @companyId AND AR_InvoiceHeader.PeriodID = @PeriodId AND convert(date,AR_InvoiceHeader.InvoiceDate) BETWEEN @FromDate AND @ToDate And SET_DocumentType.status= 1 {5} ) TABInvoice where TABInvoice.companyID = @companyId {8} {9}
