UNION ALL ---------- Payment ---------- SELECT SET_DocumentType.DocumentType, AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PaymentSupplierDetail.PaymentSupplierID as SourceID, (Case AP_PaymentSupplierDetail.TransactionType when 'Debit' then AP_PaymentSupplierDetail.Amount else AP_PaymentSupplierDetail.Amount * -1 end) as Amount, AP_PaymentHeader.PaymentServerOrderNo AS InstrumentNo, IsNull(AP_PaymentHeader.Comments, '') + (Case When AP_PaymentHeader.ReversalComments IS NULL Then '' Else ' ' + AP_PaymentHeader.ReversalComments End) AS Comments, case when AP_PaymentHeader.POHeaderID is null then (ISNULL( ( SELECT STUFF( ( SELECT AR_InvoiceHeader.InvoiceNumber FROM AP_PaymentHeader childPayment LEFT JOIN AP_PaymentInvoicesDetail ON AP_PaymentInvoicesDetail.PaymentHeaderID = childPayment.PaymentID AND AP_PaymentInvoicesDetail.CompanyID = childPayment.CompanyID AND AP_PaymentInvoicesDetail.PeriodID = childPayment.PeriodID AND AP_PaymentInvoicesDetail.Status = 1 LEFT JOIN AR_InvoiceHeader ON AR_InvoiceHeader.InvoiceID = AP_PaymentInvoicesDetail.InvoiceHeaderID AND AR_InvoiceHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID AND AR_InvoiceHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID AND AR_InvoiceHeader.Status = 1 LEFT JOIN AR_InvoiceDetail ON AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID AND AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status = 1 where childPayment.PaymentID = payment.PaymentID and childPayment.CompanyID = payment.CompanyID and childPayment.PeriodID = payment.PeriodID AND childPayment.Status= 1 ORDER BY AR_InvoiceHeader.InvoiceNumber FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceNumbers FROM AP_PaymentHeader payment where payment.PaymentID = AP_PaymentHeader.PaymentID and payment.CompanyID = AP_PaymentHeader.CompanyID and payment.PeriodID = AP_PaymentHeader.PeriodID And payment.Status= 1
), '')) else (Select DocumentNumber from AP_PurchaseOrderHeader where AP_PurchaseOrderHeader.POHeaderID = AP_PaymentHeader.POHeaderID and AP_PurchaseOrderHeader.CompanyID = AP_PaymentHeader.CompanyID and AP_PurchaseOrderHeader.PeriodID = AP_PaymentHeader.PeriodID And AP_PurchaseOrderHeader.status = 1 ) end as InvoiceNumbers, ISNULL( ( SELECT STUFF( ( SELECT ', ' + AP_PaymentDetail.InvoiceDocumentNo FROM AP_PaymentDetail WHERE payment1.PaymentID = AP_PaymentDetail.PaymentHeaderID And AP_PaymentDetail.Status= 1 ORDER BY AP_PaymentDetail.InvoiceDocumentNo FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceDocumentNo FROM AP_PaymentHeader payment1 where payment1.PaymentID = AP_PaymentHeader.PaymentID and payment1.CompanyID = AP_PaymentHeader.CompanyID and payment1.PeriodID = AP_PaymentHeader.PeriodID AND payment1.Status= 1 ), '') as InvoiceDocumentNo, ISNULL(AP_PaymentHeader.DocumentNo, 0) AS DocumentNo, AP_PaymentHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount , IsNull(AP_Payment_AccountsDetail.Amount, 0) * -1 As ForAlhajAmount ,AP_PaymentHeader.StatusCode, '' AS FAX, '' AS SheetNo FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 --AND AP_PaymentHeader.StatusCode = 1 INNER Join AP_PaymentSupplierDetail on AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID and AP_PaymentSupplierDetail.Status = 1 INNER JOIN AR_SET_Customer ON AP_PaymentSupplierDetail.SupplierID = AR_SET_Customer.CustomerID --AND AP_PaymentSupplierDetail.CompanyID = AND AP_PaymentSupplierDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 -- AND AR_SET_Customer.IsActive = 1 left join AP_Payment_AccountsDetail on AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_Payment_AccountsDetail.IsBP <> 0 and AP_Payment_AccountsDetail.TransactionType = 'Credit' and AP_Payment_AccountsDetail.Status = 1
INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID and AR_SET_BusinessPartnerTypes.TypeCode = AP_PaymentSupplierDetail.BusinessPartnerTypeID {7} WHERE AP_PaymentHeader.CompanyID = @CompanyId AND AP_PaymentHeader.PeriodID = @PeriodId AND convert(date,AP_PaymentHeader.DocumentDate) BETWEEN @FromDate AND @ToDate And SET_DocumentType.Status= 1 {0} {1} {6} GROUP BY AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AP_PaymentSupplierDetail.PaymentSupplierID, AP_PaymentSupplierDetail.TransactionType, AP_PaymentSupplierDetail.Amount, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.DocumentDate, SET_DocumentType.DocumentType, AP_PaymentHeader.PaymentID, AP_PaymentHeader.CompanyID, AP_PaymentHeader.PeriodID, AP_PaymentHeader.Comments, AP_PaymentHeader.POHeaderID, AP_PaymentHeader.PaymentServerOrderNo, AP_Payment_AccountsDetail.Amount, AP_PaymentHeader.ReversalComments ,AP_PaymentHeader.StatusCode UNION ALL
-- PAYMENT -- SINGLE BUSINESS PARTNER CASE SELECT SET_DocumentType.DocumentType, AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AP_PaymentHeader.PaymentID as SourceID, (Case when AP_PaymentHeader.CustomerTransactionType is not null then AP_PaymentHeader.Amount * -1 else AP_PaymentHeader.Amount end) as Amount, AP_PaymentHeader.PaymentServerOrderNo AS InstrumentNo, AP_PaymentHeader.Comments + (Case When AP_PaymentHeader.ReversalComments IS NULL Then '' Else ' ' + AP_PaymentHeader.ReversalComments End) AS Comments, case when AP_PaymentHeader.POHeaderID is null then (ISNULL( ( SELECT STUFF( ( SELECT distinct AR_InvoiceHeader.InvoiceNumber FROM AP_PaymentHeader childPayment LEFT JOIN AP_PaymentInvoicesDetail ON AP_PaymentInvoicesDetail.PaymentHeaderID = childPayment.PaymentID AND AP_PaymentInvoicesDetail.CompanyID = childPayment.CompanyID AND AP_PaymentInvoicesDetail.PeriodID = childPayment.PeriodID AND AP_PaymentInvoicesDetail.Status = 1 LEFT JOIN AR_InvoiceHeader ON AR_InvoiceHeader.InvoiceID = AP_PaymentInvoicesDetail.InvoiceHeaderID AND AR_InvoiceHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID AND AR_InvoiceHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID AND AR_InvoiceHeader.Status = 1 LEFT JOIN AR_InvoiceDetail ON AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID AND AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status = 1 where childPayment.PaymentID = payment.PaymentID and childPayment.CompanyID = payment.CompanyID and childPayment.PeriodID = payment.PeriodID And childPayment.Status= 1 ORDER BY AR_InvoiceHeader.InvoiceNumber FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 0, '') AS InvoiceNumbers FROM AP_PaymentHeader payment where payment.PaymentID = AP_PaymentHeader.PaymentID and payment.CompanyID = AP_PaymentHeader.CompanyID and payment.PeriodID = AP_PaymentHeader.PeriodID And payment.Status= 1 ), '')) else (Select DocumentNumber from AP_PurchaseOrderHeader where AP_PurchaseOrderHeader.status= 1 And AP_PurchaseOrderHeader.POHeaderID = AP_PaymentHeader.POHeaderID and AP_PurchaseOrderHeader.CompanyID = AP_PaymentHeader.CompanyID and AP_PurchaseOrderHeader.PeriodID = AP_PaymentHeader.PeriodID ) end as InvoiceNumbers, ISNULL( ( SELECT STUFF( ( SELECT ', ' + AP_PaymentDetail.InvoiceDocumentNo FROM AP_PaymentDetail WHERE payment1.PaymentID = AP_PaymentDetail.PaymentHeaderID And AP_PaymentDetail.Status= 1 ORDER BY AP_PaymentDetail.InvoiceDocumentNo FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS InvoiceDocumentNo FROM AP_PaymentHeader payment1 where payment1.PaymentID = AP_PaymentHeader.PaymentID and payment1.CompanyID = AP_PaymentHeader.CompanyID and payment1.PeriodID = AP_PaymentHeader.PeriodID And payment1.Status= 1 ), '') as InvoiceDocumentNo, ISNULL(AP_PaymentHeader.DocumentNo, 0) AS DocumentNo, AP_PaymentHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount , IsNull(AP_Payment_AccountsDetail.Amount, 0) * -1 As ForAlhajAmount , AP_PaymentHeader.StatusCode, '' AS FAX, '' AS SheetNo FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 --AND AP_PaymentHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
left join AP_Payment_AccountsDetail on AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_Payment_AccountsDetail.IsBP <> 0 and AP_Payment_AccountsDetail.TransactionType = 'Credit' and AP_Payment_AccountsDetail.Status = 1 {7} WHERE AP_PaymentHeader.CompanyID = @CompanyId AND AP_PaymentHeader.PeriodID = @PeriodId AND convert(date,AP_PaymentHeader.DocumentDate) BETWEEN @FromDate AND @ToDate And SET_DocumentType.Status= 1 {0} {1} {6} GROUP BY AP_PaymentHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AP_PaymentHeader.CustomerTransactionType, AP_PaymentHeader.Amount, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.DocumentDate, SET_DocumentType.DocumentType, AP_PaymentHeader.PaymentID, AP_PaymentHeader.CompanyID, AP_PaymentHeader.PeriodID,AP_PaymentHeader.Comments, AP_PaymentHeader.POHeaderID,AP_PaymentHeader.PaymentServerOrderNo ,AP_Payment_AccountsDetail.Amount, AP_PaymentHeader.ReversalComments ,AP_PaymentHeader.StatusCode UNION ALL -----------Sale Invoice Header----------- select TAB.DocumentType,TAB.CreateDate,CustomerID,BusinessPartnerName,SourceID,round(sum(Amount),2) as Amount,InstrumentNo,Comments,InvoiceNumbers,InvoiceDocumentNo,DocumentNo,DocumentDate,FreightAmount,ForAlhajAmount,StatusCode, '' AS FAX, '' AS SheetNo from (
SELECT SET_DocumentType.DocumentType, SAL_InvoiceHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_InvoiceHeader.InvoiceID as SourceID,
case when SET_DocumentType.DocumentType = 'Credit Note' then SAL_InvoiceHeader.AmountPaid * -1 else
case when isnull((select FieldValue1 from Set_Parameter where FieldName = 'SROPercent'),0) != 0 then ( case isnull(AR_SET_BusinessPartner.BusinessPartnerName,'') when 'S.R.O' then (case isnull(Fabrics_SAL_InvoiceDetail.FurtherTax,0) when 0 then ((Fabrics_SAL_InvoiceDetail.Amount * (Fabrics_SAL_InvoiceDetail.GST + Fabrics_SAL_InvoiceDetail.FurtherTax)/100 )* isnull((select FieldValue1 from Set_Parameter where FieldName = 'SROPercent'),0) / 100) else 0 end) when 'Customer' then ( case isnull(FurtherTax,0) when 0 then SAL_InvoiceHeader.AmountPaid - ((Fabrics_SAL_InvoiceDetail.Amount * (GST + FurtherTax)/100 ) * isnull((select FieldValue1 from Set_Parameter where FieldName = 'SROPercent'),0) / 100) else SAL_InvoiceHeader.AmountPaid + (SAL_InvoiceHeader.AmountPaid * FurtherTax / 100) end ) else 0 end ) else SAL_InvoiceHeader.AmountPaid end end as Amount,
'0' AS InstrumentNo, SAL_InvoiceHeader.description AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, SAL_InvoiceHeader.InvoiceDate AS DocumentDate, CASE WHEN GL_TransactionDetail.TransactionType = 'Debit' THEN ISNULL(SAL_InvoiceHeader.FreightAmount * -1, 0) else ISNULL(SAL_InvoiceHeader.FreightAmount, 0) end as FreightAmount , 0 As ForAlhajAmount,SAL_InvoiceHeader.StatusCode FROM SET_DocumentType INNER JOIN SAL_InvoiceHeader ON SET_DocumentType.CompanyID = SAL_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_InvoiceHeader.InvoiceType AND SAL_InvoiceHeader.Status = 1 left join Fabrics_SAL_InvoiceDetail on Fabrics_SAL_InvoiceDetail.InvoiceHeaderID = SAL_InvoiceHeader.InvoiceID and Fabrics_SAL_InvoiceDetail.status = 1 INNER JOIN AR_SET_Customer ON SAL_InvoiceHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 --AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 --AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode --AND AR_SET_BusinessPartner.BusinessPartnerName = 'Customer' LEFT JOIN GL_TransactionDetail ON GL_TransactionDetail.CodeCombinationID = SAL_InvoiceHeader.FreightCode AND GL_TransactionDetail.SourceHeaderID = SAL_InvoiceHeader.InvoiceID AND GL_TransactionDetail.CompanyID = SAL_InvoiceHeader.CompanyID AND GL_TransactionDetail.PeriodID = SAL_InvoiceHeader.PeriodID And GL_TransactionDetail.Status= 1 {7} WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND convert(date,SAL_InvoiceHeader.InvoiceDate) BETWEEN @FromDate AND @ToDate And SET_DocumentType.Status= 1 {3} GROUP BY SAL_InvoiceHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceID, SAL_InvoiceHeader.AmountPaid, SAL_InvoiceHeader.InvoiceNumber, SAL_InvoiceHeader.InvoiceDate, SET_DocumentType.DocumentType, GL_TransactionDetail.TransactionType, SAL_InvoiceHeader.FreightAmount,SAL_InvoiceHeader.StatusCode ,GL_TransactionDetail.Amount
,Fabrics_SAL_InvoiceDetail.Amount,Fabrics_SAL_InvoiceDetail.GST,Fabrics_SAL_InvoiceDetail.FurtherTax ,AR_SET_BusinessPartner.BusinessPartnerName,SAL_InvoiceHeader.description ) as TAB group by TAB.DocumentType,TAB.CreateDate,CustomerID,BusinessPartnerName,SourceID,InstrumentNo,Comments,InvoiceNumbers,InvoiceDocumentNo,DocumentNo,DocumentDate,FreightAmount,ForAlhajAmount,StatusCode
