e = AR_ReceiptCustomerDetail.BusinessPartnerTypeID INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate {0} {1} {4} GROUP BY AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.ReceiptCustomerID ) OpeningTAB GROUP BY OpeningTAB.CustomerID, OpeningTAB.Name
