r.vendorID is null then (Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceSupplierDetail.Amount else AR_InvoiceSupplierDetail.Amount * -1 end) else ( Case when AR_InvoiceSupplierDetail.TransactionType = 'Debit' then AR_InvoiceHeader.AmountPaid when SET_DocumentType.DocumentType = 'Debit Note' then AR_InvoiceHeader.AmountPaid else (Isnull(AR_InvoiceHeader.AmountPaid,0) + Isnull(AR_InvoiceHeader.FreightAmount,0) - ISnull(AR_InvoiceHeader.OtherAmount,0)) * -1 end ) end as Amount, '0' AS InstrumentNo, AR_InvoiceHeader.Description AS Comments,AR_InvoiceSupplierDetail.Narration as DetailNarration ,AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.InvoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceHeader.BusinessPartnerTypeID LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode {7} WHERE AR_InvoiceHeader.CompanyID = @companyId AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate {5} ) TABInvoice where TABInvoice.companyID = @companyId {8} {9}
