rtnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AND AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate between @FromDate and @Todate and SET_DocumentType.DocumentType like '%opening%' {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.ReceiptCustomerID, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, Comments, AR_ReceiptTransactionHeader.ReversalComments,AR_ReceiptCustomerDetail.Narration
