STUFF((SELECT ', ' + PBD.InstrumentNo FROM AP_PaymentBanksDetail PBD WHERE PBD.PaymentHeaderID = AP_PaymentHeader.PaymentID FOR XML PATH('')), 1, 1, '') AS InstrumentNo , IsNull(AP_PaymentHeader.Comments, '') + (Case When AP_PaymentHeader.ReversalComments IS NULL Then '' Else ' ' + AP_PaymentHeader.ReversalComments End) AS Comments, AP_PaymentSupplierDetail.Narration as DetailNarration,
