er.BusinessPartnerName as BPType ,'' as GRN_NO ,(Select DocumentNumber from AP_PurchaseOrderHeader where AP_PurchaseOrderHeader.POHeaderID = AP_PaymentHeader.POHeaderID and AP_PurchaseOrderHeader.CompanyID = AP_PaymentHeader.CompanyID and AP_PurchaseOrderHeader.PeriodID = AP_PaymentHeader.PeriodID ) as PO_NO FROM SET_DocumentType INNER JOIN AP_PaymentHeader ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 -- Left Join AP_PaymentBanksDetail on AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID --and AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID --and AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID -- AND AP_PaymentBanksDetail.Status=1 INNER JOIN AR_SET_Customer ON AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID --AND AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AP_PaymentHeader.BusinessPartnerTypeID INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
