m SAL_InvoiceHeader invHdr inner join SAL_InvoiceDetail invdtl on invdtl.InvoiceHeaderID = invHdr.InvoiceID and invdtl.CompanyID = invHdr.CompanyID and invdtl.PeriodID = invHdr.PeriodID inner join INV_StockTransactionDetail stkdtl on stkdtl.StockTransactionID = invdtl.StockHeaderID and stkdtl.TransactionDetailID = invdtl.StockDetailID and stkdtl.CompanyID = invdtl.CompanyID and stkdtl.PeriodID = invdtl.PeriodID and stkdtl.Status = 1
