-----------Sale Invoice Header Detail Data----------- SELECT SET_DocumentType.DocumentType, SAL_InvoiceHeader.CreateDate, SAL_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_InvoiceHeader.InvoiceID as SourceID, (case when Sal_InvoiceCustomerDetail.TransactionType ='Credit' or SET_DocumentType.DocumentType = 'Credit Note' then SUM(Sal_InvoiceCustomerDetail.Amount *-1) else SUM(Sal_InvoiceCustomerDetail.Amount) end )Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_InvoiceHeader.InvoiceNumber, 0) AS DocumentNo, SAL_InvoiceHeader.InvoiceDate AS DocumentDate, CASE WHEN GL_TransactionDetail.TransactionType = 'Debit' THEN ISNULL(SAL_InvoiceHeader.FreightAmount * -1, 0) else ISNULL(SAL_InvoiceHeader.FreightAmount, 0) end as FreightAmount , 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO FROM SET_DocumentType INNER JOIN SAL_InvoiceHeader ON SET_DocumentType.CompanyID = SAL_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_InvoiceHeader.InvoiceType inner join Sal_InvoiceCustomerDetail on Sal_InvoiceCustomerDetail.InvoiceHeaderID = SAL_InvoiceHeader.InvoiceID and Sal_InvoiceCustomerDetail.CompanyID = SAL_InvoiceHeader.CompanyID and Sal_InvoiceCustomerDetail.PeriodID = SAL_InvoiceHeader.PeriodID and Sal_InvoiceCustomerDetail.Status = 1 INNER JOIN AR_SET_Customer ON Sal_InvoiceCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND Sal_InvoiceCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND Sal_InvoiceCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1
{1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = Sal_InvoiceCustomerDetail.BusinessPartnerTypeID {0} inner JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT JOIN GL_TransactionDetail ON GL_TransactionDetail.CodeCombinationID = SAL_InvoiceHeader.FreightCode AND GL_TransactionDetail.SourceHeaderID = SAL_InvoiceHeader.InvoiceID AND GL_TransactionDetail.CompanyID = SAL_InvoiceHeader.CompanyID AND GL_TransactionDetail.PeriodID = SAL_InvoiceHeader.PeriodID {7} WHERE SAL_InvoiceHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND SAL_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {3} GROUP BY SAL_InvoiceHeader.CreateDate,SAL_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceID, Sal_InvoiceCustomerDetail.Amount, SAL_InvoiceHeader.InvoiceNumber, SAL_InvoiceHeader.InvoiceDate, SET_DocumentType.DocumentType, GL_TransactionDetail.TransactionType, SAL_InvoiceHeader.FreightAmount ,Sal_InvoiceCustomerDetail.TransactionType ,AR_SET_BusinessPartner.BusinessPartnerName
union all --RECEIPT TRANSACTION SELECT distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, Case when ( select Amount from AR_ReceiptAccountsDetail rad where rad.TransactionType = 'Credit' and rad.ReceiptHeaderID = AR_ReceiptAccountsDetail.ReceiptHeaderID and rad.ReceiptAccountID = AR_ReceiptAccountsDetail.ReceiptAccountID ) is null then AR_ReceiptTransactionHeader.Amount * -1 else AR_ReceiptTransactionHeader.Amount * -1 end as Amount,
STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo , IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as DetailNarration, STUFF((SELECT ', ' + SAL_InvoiceHeader.invoicenumber FROM AR_ReceiptInvoicesDetail PBD inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID = PBD.InvoiceHeaderID and SAL_InvoiceHeader.Status = 1 and SAL_InvoiceHeader.CompanyID = PBD.CompanyID and SAL_InvoiceHeader.PeriodID = PBD.PeriodID WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and PBD.CompanyID = AR_ReceiptTransactionHeader.CompanyID --and PBD.PeriodID = AR_ReceiptTransactionHeader.PeriodID FOR XML PATH('')), 1, 1, '') AS InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO ,STUFF(( select distinct ', ' + convert(varchar(10),isnull(SAL_ContractHeader.ContractNo,SAL_OrderHeader.ContractNo)) from AR_ReceiptTransactionHeader recpt left join SAL_ContractHeader on SAL_ContractHeader.ContractID = recpt.SourceHeaderID and SAL_ContractHeader.CompanyID = recpt.CompanyID and SAL_ContractHeader.PeriodID = recpt.PeriodID
left join SAL_OrderHeader on SAL_OrderHeader.OrderID = recpt.SourceHeaderID and SAL_OrderHeader.CompanyID = recpt.CompanyID and SAL_OrderHeader.PeriodID = recpt.PeriodID
where recpt.ReceiptTransactionID = AR_ReceiptTransactionHeader.ReceiptTransactionID and recpt.CompanyID = AR_ReceiptTransactionHeader.CompanyID and recpt.PeriodID = AR_ReceiptTransactionHeader.PeriodID
FOR XML PATH('')), 1, 1, '') AS PO_NO FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1
--Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptBankID=AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID=AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID=AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1
INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptTransactionHeader.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and AR_ReceiptTransactionHeader.ReceiptTransactionID not in ( select ReceiptHeaderID from AR_ReceiptCustomerDetail inner join AR_ReceiptTransactionHeader RecHDR on RecHDR.ReceiptTransactionID = AR_ReceiptTransactionHeader.ReceiptTransactionID and RecHDR.CompanyID = AR_ReceiptTransactionHeader.CompanyID and RecHDR.PeriodID = AR_ReceiptTransactionHeader.PeriodID inner join set_documentType on set_documentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID and set_documentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID and set_documentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID {7} where AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and set_documentType.documentType not like '%Advance Against SO%' ) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptTransactionHeader.ReceiptTransactionID, AR_ReceiptAccountsDetail.ReceiptHeaderID, AR_ReceiptAccountsDetail.ReceiptAccountID,AR_ReceiptAccountsDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, ReversalComments ,AR_ReceiptTransactionHeader.ReceiptTransactionID ,AR_SET_BusinessPartner.BusinessPartnerName,AR_ReceiptTransactionHeader.SourceHeaderID ,AR_ReceiptTransactionHeader.PeriodID UNION ALL -- Receipt Transaction Without Opening SELECT Distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptCustomerDetail.ReceiptCustomerID as SourceID, Case when AR_ReceiptCustomerDetail.TransactionType = 'Debit' then AR_ReceiptCustomerDetail.Amount else AR_ReceiptCustomerDetail.Amount * -1 end as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and PBD.CompanyID = AR_ReceiptTransactionHeader.CompanyID and PBD.PeriodID = AR_ReceiptTransactionHeader.PeriodID FOR XML PATH('')), 1, 1, '') AS InstrumentNo , IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, AR_ReceiptCustomerDetail.Narration as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.status = 1
--Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptBankID=AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID=AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID=AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1
INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate and SET_DocumentType.DocumentType not like '%opening%' And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.ReceiptCustomerID, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType,AR_ReceiptTransactionHeader.Comments, AR_ReceiptTransactionHeader.ReversalComments,AR_ReceiptCustomerDetail.Narration,AR_ReceiptTransactionHeader.ReceiptTransactionID ,AR_ReceiptTransactionHeader.CompanyID,AR_ReceiptTransactionHeader.PeriodID ,AR_SET_BusinessPartner.BusinessPartnerName UNION ALL -- Receipt Transaction [Only Opening]
SELECT Distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptCustomerDetail.ReceiptCustomerID as SourceID, Case when AR_ReceiptCustomerDetail.TransactionType = 'Debit' then AR_ReceiptCustomerDetail.Amount else AR_ReceiptCustomerDetail.Amount * -1 end as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo , IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, AR_ReceiptCustomerDetail.Narration as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptCustomerDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptCustomerDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptCustomerDetail.status = 1 -- Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptBankID=AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID=AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID=AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1 INNER JOIN AR_SET_Customer ON AR_ReceiptCustomerDetail.CustomerID = AR_SET_Customer.CustomerID --AND AR_ReceiptCustomerDetail.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptCustomerDetail.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptCustomerDetail.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode LEFT Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate between @FromDate and @Todate and SET_DocumentType.DocumentType like '%opening%' And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptCustomerDetail.ReceiptCustomerID, AR_ReceiptCustomerDetail.TransactionType, AR_ReceiptCustomerDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, AR_ReceiptTransactionHeader.ReversalComments,AR_ReceiptCustomerDetail.Narration,AR_ReceiptTransactionHeader.ReceiptTransactionID ,AR_SET_BusinessPartner.BusinessPartnerName UNION ALL -- Commission On Receipt SELECT Distinct SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, ((AR_ReceiptTransactionHeader.Amount * AR_ReceiptTransactionHeader.CommissionPercentage)/100) * -1 as Amount, STUFF((SELECT ', ' + PBD.InstrumentNo FROM AR_ReceiptBanksDetail PBD WHERE PBD.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID FOR XML PATH('')), 1, 1, '') AS InstrumentNo , IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as DetailNarration, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 -- Left Join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptBankID=AR_ReceiptTransactionHeader.ReceiptTransactionID --AND AR_ReceiptBanksDetail.CompanyID=AR_ReceiptTransactionHeader.CompanyID --AND AR_ReceiptBanksDetail.PeriodID=AR_ReceiptTransactionHeader.PeriodID --AND AR_ReceiptBanksDetail.Status=1
INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.EmployeeID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_ReceiptTransactionHeader.BusinessPartnerTypeID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptTransactionHeader.ReceiptTransactionID, AR_ReceiptTransactionHeader.CommissionPercentage, AR_ReceiptAccountsDetail.ReceiptHeaderID, AR_ReceiptAccountsDetail.ReceiptAccountID,AR_ReceiptAccountsDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.Comments, ReversalComments ,AR_ReceiptTransactionHeader.ReceiptTransactionID ,AR_SET_BusinessPartner.BusinessPartnerName -------- SALE DISCOUNT -----------
union All SELECT distinct SET_DocumentType.DocumentType, SAL_DiscountTransactionHeader.CreateDate, SAL_DiscountTransactionHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_DiscountTransactionHeader.DiscountTransactionHeaderID as SourceID, (SAL_DiscountTransactionHeader.CalculatedAmount * -1) as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration ,'' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_DiscountTransactionHeader.DiscountTransactionHeaderID, 0) AS DocumentNo, SAL_DiscountTransactionHeader.RunDateTime AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO FROM SET_DocumentType INNER JOIN SAL_DiscountTransactionHeader ON SET_DocumentType.CompanyID = SAL_DiscountTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_DiscountTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_DiscountTransactionHeader.DocumentTypeID INNER JOIN AR_SET_Customer ON SAL_DiscountTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_DiscountTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_DiscountTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode {7} WHERE SAL_DiscountTransactionHeader.CompanyID in @CompanyID and AR_SET_Customer.PeriodID = @PeriodID AND SAL_DiscountTransactionHeader.RunDateTime BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null)
union all
------------------------------------- KNON of Advance SELECT distinct SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, AR_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, GL_TransactionDetail.SerialNo as SourceID, (GL_TransactionDetail.Amount) as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration ,'' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.invoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.invoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO
FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AR_InvoiceHeader.VendorID = AR_SET_Customer.CustomerID --AND AR_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AR_InvoiceHeader.InvoiceNumber and GL_TransactionHeader.DocumentTypeID = AR_InvoiceHeader.InvoiceType and GL_TransactionHeader.FiscalID = AR_InvoiceHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON dbo.GL_TransactionHeader.TransactionID = dbo.GL_TransactionDetail.TransactionID AND dbo.GL_TransactionHeader.PeriodID = dbo.GL_TransactionDetail.PeriodID AND dbo.GL_TransactionHeader.CompanyID = dbo.GL_TransactionDetail.CompanyID
AND (dbo.GL_TransactionDetail.CodeCombinationID In (SELECT Distinct DefaultAccountCode FROM dbo.SET_DocumentType WHERE (DocumentType Like 'Advance Against PO%') AND (CompanyID in @CompanyID) AND (PeriodID = @PeriodID))) AND (dbo.GL_TransactionDetail.TransactionType = 'Credit')
LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.status = 1 LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID AND AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceHeader.BusinessPartnerTypeID
LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
WHERE AR_InvoiceHeader.CompanyID in @CompanyID AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) {5} {12} {0}
UNION ALL
---------- Purchase Return ----------
select distinct FinTab.DocumentType, FinTab.CreateDate,CompanyID, FinTab.CustomerID, FinTab.BusinessPartnerName, FinTab.SourceID, FinTab.Amount, FinTab.InstrumentNo, FinTab.Narration as Comments,FinTab.DetailNarration , FinTab.InvoiceNumbers, FinTab.InvoiceDocumentNo, FinTab.DocumentNo , FinTab.DocumentDate, FinTab.FreightAmount, FinTab.ForAlhajAmount ,FinTab.BPType,GRN_NO,PO_NO from ( Select distinct GL_TransactionHeader.DocumentDate,GL_TransactionHeader.CreateDate,GL_TransactionHeader.CompanyID, Set_DocumentType.DocumentType ,Set_DocumentType.DocumentTypeID, Set_CostCenter.CostCenterName, AR_Set_Customer.CustomerID, AR_Set_Customer.CustomerName as BusinessPartnerName, GL_TransactionHeader.DocumentNo, '' as DetailNarration, ' ' as Narration, GL_TransactionDetail.CodeCombinationID as SupplierAccountCode, ( Case When GL_TransactionDetail.TransactionType = 'Debit' Then GL_TransactionDetail.Amount When GL_TransactionDetail.TransactionType = 'Credit' then GL_TransactionDetail.Amount * -1 Else 0 End ) as Amount, GL_codecombinationDetail.Description as CodeDescription ,'' AS InstrumentNo ,AR_InvoiceHeader.InvoiceNumber as InvoiceDocumentNo , 0 as FreightAmount , 0 As ForAlhajAmount ,AR_InvoiceHeader.VendorReferenceNumber as InvoiceNumbers ,STUFF(( select distinct ', ' + convert(varchar(10),INV_StockTransactionheader.DocumentNo) from INV_StockTransactionDetail inner join INV_StockTransactionheader on INV_StockTransactionheader.StockTransactionID = INV_StockTransactionDetail.StockTransactionID and INV_StockTransactionheader.CompanyID = INV_StockTransactionDetail.CompanyID and INV_StockTransactionheader.PeriodID = INV_StockTransactionDetail.PeriodID inner join AR_InvoiceDetail invDtl on invDtl.StockHeaderID = INV_StockTransactionDetail.StockTransactionID and invDtl.StockDetailID = INV_StockTransactionDetail.TransactionDetailID and invDtl.CompanyID = INV_StockTransactionDetail.CompanyID and invDtl.PeriodID = INV_StockTransactionDetail.PeriodID and invDtl.Status = 1 where INV_StockTransactionDetail.Status = 1 and invDtl.InvoiceHeaderID = AR_InvoiceDetail.InvoiceHeaderID and invDtl.CompanyID = AR_InvoiceDetail.CompanyID and invDtl.PeriodID = AR_InvoiceDetail.PeriodID FOR XML PATH('')), 1, 1, '') AS GRN_NO ,STUFF(( Select distinct ', ' + convert(varchar(10), AP_PurchaseOrderHeader.DocumentNumber) from AP_PurchaseOrderHeader left join AR_InvoiceDetail on AR_InvoiceDetail.PurchaseOrderHeaderID=AP_PurchaseOrderHeader.POHeaderID And AP_PurchaseOrderHeader.CompanyID=AR_InvoiceDetail.CompanyID And AP_PurchaseOrderHeader.PeriodID=AR_InvoiceDetail.PeriodID And AP_PurchaseOrderHeader.Status=1 Where AR_InvoiceDetail.InvoiceHeaderID=AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.CompanyID=AR_InvoiceHeader.CompanyID And AR_InvoiceDetail.PeriodID=AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.Status=1
FOR XML PATH('')), 1, 1, '') AS PO_NO ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,INV_StockTransactionHeader.StockTransactionID as SourceID FROM INV_StockTransactionHeader INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = INV_StockTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = INV_StockTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = INV_StockTransactionHeader.DocumentTypeID and INV_StockTransactionHeader.status = 1
INNER JOIN AR_SET_Customer ON INV_StockTransactionHeader.BusinessPartnerID = AR_SET_Customer.CustomerID AND INV_StockTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1
{1} inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = INV_StockTransactionHeader.DocumentNo and GL_TransactionHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID and INV_StockTransactionHeader.FiscalID = GL_TransactionHeader.FiscalID and GL_TransactionHeader.Status=1
INNER JOIN dbo.GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionDetail.TransactionType = 'Debit' AND GL_TransactionDetail.Status=1 Inner JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = INV_StockTransactionHeader.BusinessPartnerID AND AR_SET_BusinessPartnerTypes.PeriodID = INV_StockTransactionHeader.PeriodID AND AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = INV_StockTransactionHeader.BusinessPartnerTypeID {7}
Left Join Set_CostCenter On Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join GL_codecombinationDetail on GL_codecombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID
----------------------
inner JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 and AR_InvoiceHeader.InvoiceID = INV_StockTransactionHeader.InvoiceHeaderID LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceDetail.Status=1 LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.Status=1
----------------------
WHERE INV_StockTransactionHeader.CompanyID in @CompanyID AND INV_StockTransactionHeader.PeriodID = @PeriodId AND INV_StockTransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate And (Set_DocumentType.DocumentTypeID = @DocumentTypeID Or @DocumentTypeID is null) and INV_StockTransactionHeader.BusinessPartnerTypeID is not null and INV_StockTransactionHeader.InvoiceHeaderID is not null --{3}
) As FinTab Group By FinTab.DocumentDate,CreateDate,CompanyID, FinTab.DocumentType,FinTab.DocumentTypeID, FinTab.CostCenterName , FinTab.CustomerID, FinTab.BusinessPartnerName, FinTab.DocumentNo, Fintab.Narration, FinTab.SupplierAccountCode, FinTab.CodeDescription,InstrumentNo,FinTab.InvoiceNumbers,GRN_NO,PO_NO,FinTab.SourceID,FinTab.Amount ,FinTab.DetailNarration,FinTab.InvoiceDocumentNo,FinTab.FreightAmount,FinTab.ForAlhajAmount,FinTab.BPType
union all
------------------------------------- KNON of Advance cOPY OF 2 SELECT distinct SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, AR_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, GL_TransactionDetail.SerialNo + 1 as SourceID, (GL_TransactionDetail.Amount * -1) as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration ,'' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.invoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.invoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO
FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AR_InvoiceHeader.VendorID = AR_SET_Customer.CustomerID --AND AR_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AR_InvoiceHeader.InvoiceNumber and GL_TransactionHeader.DocumentTypeID = AR_InvoiceHeader.InvoiceType and GL_TransactionHeader.FiscalID = AR_InvoiceHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON dbo.GL_TransactionHeader.TransactionID = dbo.GL_TransactionDetail.TransactionID AND dbo.GL_TransactionHeader.PeriodID = dbo.GL_TransactionDetail.PeriodID AND dbo.GL_TransactionHeader.CompanyID = dbo.GL_TransactionDetail.CompanyID
AND (dbo.GL_TransactionDetail.CodeCombinationID In (SELECT Distinct DefaultAccountCode FROM dbo.SET_DocumentType WHERE (DocumentType Like 'Advance Against PO%') AND (CompanyID in @CompanyID) AND (PeriodID = @PeriodID))) AND (dbo.GL_TransactionDetail.TransactionType = 'Credit')
LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.status = 1 LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID --AND AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceSupplierDetail.BusinessPartnerTypeID AND AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID
LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
WHERE AR_InvoiceHeader.CompanyID in @CompanyID AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and isnull(GL_TransactionDetail.Narration,'') like '%GST%' and isnull(AR_SET_BusinessPartner.BusinessPartnerName,'') like '%GST%' {0} {5}
{10}
{11}
{12}
union all
------------------------------------- KNON of Advance cOPY OF 2 Non GST SELECT distinct SET_DocumentType.DocumentType, AR_InvoiceHeader.CreateDate, AR_InvoiceHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, GL_TransactionDetail.SerialNo + 1 as SourceID, (GL_TransactionDetail.Amount * -1) as Amount, '0' AS InstrumentNo, '' AS Comments, '' as DetailNarration ,'' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_InvoiceHeader.invoiceNumber, 0) AS DocumentNo, AR_InvoiceHeader.invoiceDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount ,AR_SET_BusinessPartner.BusinessPartnerName as BPType ,'' as GRN_NO,'' as PO_NO
FROM SET_DocumentType INNER JOIN AR_InvoiceHeader ON SET_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID AND SET_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AR_InvoiceHeader.VendorID = AR_SET_Customer.CustomerID --AND AR_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 {1} inner join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = AR_InvoiceHeader.InvoiceNumber and GL_TransactionHeader.DocumentTypeID = AR_InvoiceHeader.InvoiceType and GL_TransactionHeader.FiscalID = AR_InvoiceHeader.FiscalID INNER JOIN dbo.GL_TransactionDetail ON dbo.GL_TransactionHeader.TransactionID = dbo.GL_TransactionDetail.TransactionID AND dbo.GL_TransactionHeader.PeriodID = dbo.GL_TransactionDetail.PeriodID AND dbo.GL_TransactionHeader.CompanyID = dbo.GL_TransactionDetail.CompanyID
AND (dbo.GL_TransactionDetail.CodeCombinationID In (SELECT Distinct DefaultAccountCode FROM dbo.SET_DocumentType WHERE (DocumentType Like 'Advance Against PO%') AND (CompanyID in @CompanyID) AND (PeriodID = @PeriodID))) AND (dbo.GL_TransactionDetail.TransactionType = 'Credit')
LEFT JOIN AR_InvoiceDetail on AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID LEFT JOIN AR_InvoiceSupplierDetail on AR_InvoiceSupplierDetail.CompanyID = AR_InvoiceHeader.CompanyID and AR_InvoiceSupplierDetail.PeriodID = AR_InvoiceHeader.PeriodID and AR_InvoiceSupplierDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID and AR_InvoiceSupplierDetail.status = 1 LEFT JOIN AR_SET_Customer ASCUS ON AR_InvoiceSupplierDetail.SupplierID = ASCUS.CustomerID --AND AR_InvoiceSupplierDetail.CompanyID = ASCUS.CompanyID AND AR_InvoiceSupplierDetail.PeriodID = ASCUS.PeriodID AND ASCUS.Status = 1 left JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_InvoiceHeader.vENDORid --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_InvoiceHeader.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_InvoiceHeader.PeriodID --AND AR_SET_BusinessPartnerTypes.TypeCode = AR_InvoiceSupplierDetail.BusinessPartnerTypeID AND AR_SET_BusinessPartnerTypes.FK_CodeCombinationID = GL_TransactionDetail.CodeCombinationID
LEFT JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode
WHERE AR_InvoiceHeader.CompanyID in @CompanyID AND AR_InvoiceHeader.PeriodID = @PeriodId AND AR_InvoiceHeader.InvoiceDate BETWEEN @FromDate AND @ToDate And (SET_DocumentType.DocumentTypeID =@DocumentTypeiD Or @DocumentTypeiD is Null) and isnull(GL_TransactionDetail.Narration,'') not like '%GST%' and isnull(AR_SET_BusinessPartner.BusinessPartnerName,'') not like '%GST%' {0} {5}
{10}
{11}
{12}
UNION ALL
----Sales Invoice Return SELECT SET_DocumentType.DocumentType, SAL_ReverseHeader.CreateDate, SAL_ReverseHeader.CompanyID, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS Name, SAL_ReverseHeader.ReverseHeaderID as SourceID, --case when SET_DocumentType.DocumentType = 'Credit Note' then SUM(ABS(SAL_ReverseDetail.ReversedAmount * -1)) else --SUM(ABS(SAL_ReverseDetail.ReversedAmount* -1)) end as Amount, SUM(SAL_ReverseDetail.ReversedAmount) * -1 as Amount, '0' AS InstrumentNo, GL_TransactionHeader.Narration AS Comments, '' as DetailNarration , SAL_InvoiceHeader.InvoiceNumber as InvoiceNumbers, SAL_InvoiceHeader.InvoiceNumber as InvoiceDocumentNo, ISNULL(SAL_ReverseHeader.DocumentNo, 0) AS DocumentNo, SAL_ReverseHeader.CreateDate AS DocumentDate, 0 as FreightAmount , 0 As ForAlhajAmount
,AR_SET_BusinessPartner.BusinessPartnerName as BPType,'' as GRN_NO,'' as PO_NO FROM SET_DocumentType Inner join SAL_ReverseHeader on SAL_ReverseHeader.CompanyID= SET_DocumentType.CompanyID and SAL_ReverseHeader.PeriodID = SET_DocumentType.PeriodID and SAL_ReverseHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID and SAL_ReverseHeader.Status = 1 and SET_DocumentType.Status = 1
inner join SAL_ReverseDetail on SAL_ReverseDetail.ReverseHeaderID = SAL_ReverseHeader.ReverseHeaderID and SAL_ReverseHeader.CompanyID= SAL_ReverseDetail.CompanyID and SAL_ReverseHeader.PeriodID = SAL_ReverseDetail.PeriodID and SAL_ReverseDetail.Status = 1
inner join SAL_InvoiceDetail on SAL_InvoiceDetail.InvoiceDetailID = SAL_ReverseDetail.SourceDetailID and SAL_InvoiceDetail.InvoiceHeaderID = SAL_ReverseDetail.SourceHeaderID and SAL_InvoiceDetail.CompanyID = SAL_ReverseDetail.CompanyID and SAL_InvoiceDetail.Status = 1
inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID =SAL_InvoiceDetail.InvoiceHeaderID and SAL_InvoiceHeader.InvoiceNumber = SAL_ReverseDetail.SourceCode and SAL_InvoiceHeader.InvoiceType = SAL_ReverseDetail.SourceDocumentTypeID and SAL_InvoiceHeader.status = 1 and SAL_InvoiceHeader.CompanyID = SAL_ReverseDetail.CompanyID and SAL_InvoiceHeader.CompanyID = SAL_InvoiceDetail.CompanyID
left join GL_TransactionHeader on GL_TransactionHeader.DocumentNo = SAL_ReverseHeader.DocumentNo and GL_TransactionHeader.DocumentTypeID = SAL_ReverseHeader.DocumentTypeID and GL_TransactionHeader.CompanyID = SAL_ReverseHeader.CompanyID and GL_TransactionHeader.PeriodID = SAL_ReverseHeader.PeriodID and GL_TransactionHeader.FiscalID = SAL_ReverseHeader.FiscalID and GL_TransactionHeader.Status = 1
INNER JOIN AR_SET_Customer ON SAL_InvoiceHeader.CustomerID = AR_SET_Customer.CustomerID AND SAL_InvoiceHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_InvoiceHeader.PeriodID = AR_SET_Customer.PeriodID AND SAL_InvoiceHeader.Status = 1 AND SAL_InvoiceHeader.StatusCode = 1 AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode AND AR_SET_BusinessPartner.BusinessPartnerName = 'Local Sale Debtor - Sugar'
{7} WHERE SAL_ReverseHeader.CompanyID in @CompanyID AND SAL_ReverseHeader.PeriodID = @PeriodID AND SAL_ReverseHeader.CreateDate BETWEEN @FromDate AND @ToDate and SAL_ReverseHeader.StatusCode = 1 {3} GROUP BY SAL_InvoiceHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName,AR_SET_Customer.ContactNumber , AR_SET_Customer.ContactPerson , AR_SET_Customer.AddressLine1,SAL_ReverseHeader.CreateDate,SAL_ReverseHeader.ReverseHeaderID, SET_DocumentType.DocumentType ,SAL_ReverseHeader.DocumentNo ,SAL_ReverseHeader.CompanyID,SAL_InvoiceHeader.InvoiceNumber,GL_TransactionHeader.Narration,AR_SET_BusinessPartner.BusinessPartnerName
) AS FINTAB GROUP BY DocumentType, CreateDate,CompanyID, CustomerID, NAME, SourceID, InstrumentNo, Comments,DetailNarration, InvoiceNumbers, InvoiceDocumentNo, DocumentNo, DocumentDate, FreightAmount, ForAlhajAmount ,BPType ,GRN_NO,PO_NO ) as TAb -- For Transation type Filter {2} ) as FinalTAB Left Join HRMS_Set_Employee on HRMS_Set_Employee.FK_CustomerID = FinalTAB.CustomerID {13} where FinalTAB.Amount <> 0 {14} Order By DocumentDate
